"""Migration of the seven OPP_MASTER legacy VRL validation rules."""

from decimal import Decimal
from typing import Any


_EMPTY = ""


def _get(image: dict | None, column: str) -> Any:
    if image is None:
        return _EMPTY
    return image.get(column, _EMPTY)


def _nvl(value: Any, default: Any) -> Any:
    if value is None or value == _EMPTY:
        return default
    return value


def _number(value: Any) -> Decimal:
    if value is None or value == _EMPTY:
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _date_gte(left: Any, right: Any) -> bool:
    left_text = str(left)
    right_text = str(right)
    if left_text == "00000000" or right_text == "00000000":
        return False
    return left_text >= right_text


def _error(code: str, message: str, severity: str = "BLOCK") -> dict:
    return {
        "code": code,
        "message": message,
        "severity": severity,
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Evaluate all applicable rules in legacy rule-file order."""
    errors: list[dict] = []

    amt = _number(_nvl(_get(record, "AMT"), 0))
    stat_cd = _get(record, "STAT_CD")
    lost_rsn = _get(record, "LOST_RSN")
    close_dt = _get(record, "CLOSE_DT")
    stage_pct = _number(_get(record, "STAGE_PCT"))

    # OPP-001
    if event in ("INSERT", "UPDATE"):
        if not (amt >= Decimal(0)):
            errors.append(_error("E3001", "Amount negative"))

    # OPP-002
    if event in ("INSERT", "UPDATE"):
        if not not (stat_cd == "W" and amt == Decimal(0)):
            errors.append(_error("E3002", "Won opportunity requires amount"))

    # OPP-003
    if event in ("INSERT", "UPDATE"):
        if not not (stat_cd == "L" and lost_rsn == ""):
            errors.append(_error("E3003", "Lost reason required"))

    # OPP-004
    if event in ("INSERT", "UPDATE"):
        if not not (stat_cd == "W" and close_dt == "00000000"):
            errors.append(_error("E3004", "Won opportunity requires close date"))

    # OPP-005
    if event == "UPDATE":
        old_stat_cd = _get(old, "STAT_CD")
        if not not (old_stat_cd == "W" and stat_cd != "W"):
            errors.append(_error("E3005", "Cannot reopen a won opportunity"))

    # OPP-006
    if event in ("INSERT", "UPDATE"):
        stage_is_consistent = (
            (stat_cd == "P" and stage_pct == Decimal(10))
            or (stat_cd == "Q" and stage_pct == Decimal(25))
            or (stat_cd == "N" and stage_pct == Decimal(60))
            or (stat_cd == "W" and stage_pct == Decimal(100))
            or (stat_cd == "L" and stage_pct == Decimal(0))
        )
        if not stage_is_consistent:
            errors.append(
                _error("E3006", "Stage percent inconsistent with status")
            )

    # OPP-007
    if event == "INSERT":
        if not (close_dt == "00000000" or _date_gte(close_dt, today)):
            errors.append(
                _error("E3007", "Close date in past", severity="WARN")
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return True when at least one collected failure has BLOCK severity."""
    return any(error.get("severity") == "BLOCK" for error in errors)
